package org.jsoup.nodes;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.IOException;

public class TextNodeTest {

    @Test
    public void newTextNode_GivenText_ReturnsCreatedTextNode() {
        TextNode textNode = new TextNode("Hello, World!");
        assertNotNull(textNode);
        assertEquals("textNode", textNode.nodeName());
        assertEquals("Hello, World!", textNode.text());
    }

    @Test
    public void textMethod_GivenNonBlankText_ReturnsText() {
        TextNode textNode = new TextNode("Hello, World!");
        assertEquals("Hello, World!", textNode.text());
    }

    @Test
    public void textMethod_GivenBlankText_ReturnsBlankString() {
        TextNode textNode = new TextNode("");
        assertEquals("", textNode.text());
    }

    @Test
    public void splitText_GivenOffsetSplittingAtEndOfTextNode_SplittingIsSuccessful() throws IOException {
        String originalText = "Hello, World!";
        TextNode textNode = new TextNode(originalText);
        textNode.splitText(0); // Split at the beginning of the node.
        assertEquals(originalText, originalText);
    }

    @Test
    public void splitText_GivenOffsetSplittingAtBeginningOfTextNode_SplittingIsSuccessful() throws IOException {
        String originalText = "Hello, World!";
        TextNode textNode = new TextNode(originalText + ", ");
        textNode.splitText(0); // Split at the beginning of the node.
        assertEquals(originalText, originalText);
    }

    @Test
    public void splitText_GivenOffsetSplittingInTheMiddleOfTextNode_SplittingIsSuccessful() throws IOException {
        String originalText = "Hello, World!";
        TextNode textNode = new TextNode(originalText + ", ");
        textNode.splitText(6); // Split at the middle of the node.
        assertEquals(originalText, originalText);
    }

    @Test
    public void createFromEncoded_GivenEncodedText_ReturnsCreatedTextNode() {
        String encodedText = "Hello%2C+World!";
        TextNode textNode = TextNode.createFromEncoded(encodedText);
        assertNotNull(textNode);
        assertEquals("textNode", textNode.nodeName());
        assertEquals(encodedText, textNode.text());
    }

    @Test
    public void isBlank_GivenNonBlankTextNode_ReturnsFalse() {
        TextNode textNode = new TextNode("Hello, World!");
        assertFalse(textNode.isBlank());
    }

    @Test
    public void isBlank_GivenBlankTextNode_ReturnsTrue() {
        TextNode textNode = new TextNode("");
        assertTrue(textNode.isBlank());
    }
}
